-- ============================================================================
-- BoS AHS — bos_course_syllabi seed (academic_model = 'mgr_ahs')
-- Generated from ahs_json/*.json (verbatim PDF extraction).
-- ✔ RUN AGAINST THE **MyJKKN** DATABASE (bos_course_syllabi is the local BoS table).
--   (Unlike the courses/course_mapping seeds, which target COE.)
-- 74 papers, year-based, no CO-PO/Bloom. Content = ahs_content; marks = exam_scheme;
-- rotations = internship_postings.
--
-- PREREQUISITE: apply migration supabase/migrations/20260808120000_bos_syllabus_ahs_model.sql
--   (adds academic_model / academic_year / ahs_content / exam_scheme / internship_postings).
--
-- ⚠ SCOPE ids are MyJKKN-side here (this is the MyJKKN DB), which differ from the COE ids:
--   • institutions_id  — must be the **MyJKKN** institutions UUID (FK → public.institutions).
--       The value below (9c1554e8…) is the **COE** institution id used by the course seeds;
--       verify/replace with the MyJKKN AHS institution id — they are usually DIFFERENT.
--         SELECT id, name FROM institutions WHERE institution_code = 'AHS';
--   • board_id — bos_course_syllabi.board_id has NO FK and holds the **COE** board id,
--       so a5ae913c… (the COE board) is CORRECT here.
--   • regulation_id — nullable, no FK; the COE R-2017 id is fine (or NULL).
--   • created_by — a real MyJKKN auth.users id (NOT NULL).
--   • course_id (COE bridge) left NULL — backfill via /api/bos/syllabus/backfill-course-id.
-- ============================================================================

BEGIN;

CREATE TEMP TABLE _cfg AS SELECT
  '9c1554e8-12a2-4b76-a9d6-8242bb05eba1'::uuid AS institutions_id,
  'a5ae913c-35d3-4921-96a2-793c9aff01d6'::uuid AS board_id,   -- AHS board (O-5)
  '225d6282-0bcd-47df-8427-604526f8255c'::uuid AS regulation_id,  -- R-2017
  '351c76ad-33f2-4a39-8ede-9299465b70f4'::uuid AS created_by;   -- auth.users id (NOT NULL)

INSERT INTO public.bos_course_syllabi (
  institutions_id, board_id, regulation_id, course_id,
  course_code, course_name, academic_model, academic_year,
  ahs_content, exam_scheme, internship_postings,
  created_by, version_number, is_latest, is_archived
)
SELECT
  cfg.institutions_id, cfg.board_id, cfg.regulation_id, NULL,
  s.course_code, s.course_name, 'mgr_ahs', s.academic_year,
  s.ahs_content, s.exam_scheme, s.internship,
  cfg.created_by, 1, true, false
FROM (VALUES
  ('1006', 'Anatomy, physiology, Biochemistry', 1, $ahs${"academic_year": 1, "subjects": [{"subject_no": "Paper I", "title": "Anatomy, physiology, Biochemistry", "mode": "flat", "topics": ["ANATOMY - INTRODUCTION TO ANATOMICAL TERMS ORGANIZATION OF THE HUMAN BODY: Human Cell structure; Tissues - Definition, Types, characteristics, classification, location, functions and formation; Membranes and glands - Classification and Structure", "ANATOMY - OSTEOLOGY: Upper limb - clavicle, scapula, humerous, radius, ulna; Lower limb - femur, hipbone, sacrum, tibia, fibula, Vertebral column", "ANATOMY - THORAX: Intercostal space, pleura, bony thoracic cage, ribs, sternum & thoracic vertebrae", "ANATOMY - HEART: Surface anatomy of heart; Chambers of the heart; Valves of the heart; Major blood vessels of heart; Pericardium; Coronary arteries", "ANATOMY - SKELETO-MUSCULAR SYSTEM: Muscles of thorax; Muscles of upper limb - (arm & fore arm); Flexor and extensor group of muscles (origin, insertion, action)", "ANATOMY - EXCRETORY SYSTEM: Kidneys; Ureters; Bladder", "ANATOMY - NERVOUS SYSTEM: Autonomic nervous system; Peripheral nervous system; Central nervous system", "PHYSIOLOGY - THE CELL: Cell Structure and functions of the various organelles; Endocytosis and exocytosis; Acid base balance and disturbances of acid base balances (Alkalosis, Acidosis)", "PHYSIOLOGY - CARDIO-VASCULAR SYSTEM: Physiology of the heart; Heart sounds; Cardiac cycle, Cardiac output; Auscultatory areas; Arterial Pressures, Blood Pressure; Hypertension; Electro cardiogram (ECG); Blood - Composition of Blood, functions of the blood and plasma proteins, classification and protein, Pathological and Physiological variation of the RBC, Function of Hemoglobin, Erythrocyte Sedimentation Rate (ESR), Detailed description about WBC-Total count (TC), Differential count (DC) and functions, Platelets - formation", "PHYSIOLOGY - RESPIRATORY SYSTEM: Respiratory movements; Definitions and Normal values of Lung volumes and Lung capacities", "PHYSIOLOGY - EXCRETORY SYSTEM: Normal Urinary output; Micturition; Renal function tests, renal disorders", "PHYSIOLOGY - REPRODUCTIVE SYSTEM: Formation of semen and spermatogenesis; Brief account of Menstrual Cycle, oogenesis", "PHYSIOLOGY - CENTRAL NERVOUS SYSTEM: Functions of CSF; Reflexes; Sympathetic and parasympathetic outflow; Impulse conduction; Structure of neuron; Degeneration and regeneration of nerve fibers; Cerebral blood flow", "PHYSIOLOGY - ENDOCRINE SYSTEM: Functions - Pituitary, Thyroid, Parathyroid, Adrenal, Pancreatic Hormones", "PHYSIOLOGY - DIGESTIVE SYSTEM: Physiological Anatomy of the GIT; Food Digestion in the mouth, stomach, intestine; Absorption of foods; Role of bile in digestion", "BIOCHEMISTRY - CARBOHYDRATES: Glucose and Glycogen Metabolism", "BIOCHEMISTRY - PROTEINS: Classification of proteins and functions, Metabolism", "BIOCHEMISTRY - LIPIDS: Classification of lipids and functions, Metabolism", "BIOCHEMISTRY - ENZYMES: Definition & functions; Classification; Factors affecting enzyme activity; Active site - Coenzyme - Enzyme Inhibition - Units of enzyme", "BIOCHEMISTRY - VITAMINS & MINERALS: Fat soluble vitamins (A,D,E,K); Water soluble vitamins - B-complex vitamins - principal elements (Calcium, Phosphorus, Magnesium, Sodium, Potassium, Chlorine and sulphur); Trace elements - Calorific value of foods - Basal metabolic rate (BMR) - respiratory quotient (RQ) Specific dynamic action (SDA) - Balanced diet - Marasmus - Kwashiorkar", "BIOCHEMISTRY - ACIDS AND BASES: Definition; Ph Values; Henderson - Hasselbalch equation; Buffers"], "units": [], "reference_books": ["Waugh - Ross & Wilson Anatomy & Physiology, 2008, Elsevier.", "Biochemistry for Nurses - Raju. S.M, Maddali Bindu", "Biochemistry for Nurses - Jacob Anthikad, 2nd edition"], "notes": "Combined subject paper (Anatomy + Physiology + Biochemistry) shown as Paper-1 in I YEAR of source. Anatomy Practicals: Mannequins to be provided - Osteology bones identification (rig