  ('1613', 'Surgery/Obstetrics & Gynecology', 2, $ahs${"academic_year": 2, "subjects": [{"subject_no": "Paper III", "title": "Surgery/Obstetrics & Gynecology", "mode": "units", "topics": [], "units": [{"unit_no": "Surgery/Equipments/Anaesthesiology - Unit 1", "topics": ["History of surgery, role of surgeon, importance of team work, stresses arising during operative procedure, surgical terminology, types of incision and their indications, internal & external haemorrhage - signs and symptoms, management,", "Tourniquets - use and duration of application and dangers of use.", "Sutures and surgical instruments"]}, {"unit_no": "Surgery/Equipments/Anaesthesiology - Unit 2", "topics": ["Pathogenesis, causes, epidemiology, clinical presentation, investigations and management of diseases of the following systems:-", "Skin - ulcers, wounds, burns, skin infections (boil, carbuncle, abscess, Cysts (epidermoid, dermoid) tumors (basal cell, squamous cell carcinoma and melanoma)", "Head and neck region - congenital anomalies (cleft lip, cleft palate, branchial cyst and fistula, thyroglossal cyst), parotid and submandibular glands, oral ulcers, Leukoplakia, jaw tumors, squamous carcinoma of oral cavity, pharynx and larynx.", "Thyroid and lymph nodes swelling.", "Arteries - limb ischemia, non-invasive vascular diagnostic tests, atheromatous disease, aneurysm, Raynaud's syndrome, emboli,", "Veins - Varicose veins, deep vein thrombosis and pulmonary embolism"]}, {"unit_no": "Surgery/Equipments/Anaesthesiology - Unit 3", "topics": ["Breast - mastalgia, fibroadenoma, cyst, breast abscess, cancer", "Oesophagus - dysphagia, reflux, hiatus hernia, benign and malignant tumors", "Stomach and duodenum - peptic ulcer, carcinoma, pyloric stenosis", "Small intestine - small bowel obstruction, intestinal tuberculosis", "Colon and rectum - amoebic colitis, ulcerative colitis, colorectal cancer", "Appendix - acute appendicitis, acute abdomen", "Anus - Haemorrhoids, pruritis ani, fissure and fistula-