  ('1622', 'Nephrology/pulmonology/gastroenterology/Orthopaedics', 3, $ahs${"academic_year": 3, "subjects": [{"subject_no": "Paper II", "title": "Nephrology/pulmonology/gastroenterology/Orthopaedics", "mode": "units", "topics": [], "units": [{"unit_no": "Nephrology/Pulmonology - Unit 1", "topics": ["Genito-urinary system - basics, innervations of urinary bladder in detail, microscopic structure of the kidney, Juxtaglomerular apparatus, microcirculation of kidney, histopathology of kidney, ureters, urinary bladder and urethra.", "Renal haemodynamics and glomerular filtration- renal function, renal function tests, micturition"]}, {"unit_no": "Nephrology/Pulmonology - Unit 2", "topics": ["Urinary tract pathology- basis of impaired renal function, urine analysis.", "Glomerulonephritis - classification - primary (proliferative and non-proliferative)", "Secondary glomerulonephritis - (SLE, purpura, polyarteritis, amyloidosis, diabetes, nephritic syndrome)", "Acute renal failure, progressive renal failure and end stage renal disease", "Pyelonephritis, reflux nephropathy, interstitial nephritis", "Renal and genitourinary tract tumours - renal cell carcinoma and nephroblastoma", "Renal vascular disorders, kidney changes in hypertension", "Urinary bladder - cystitis, carcinoma, urinary tract tuberculosis, urolithiasis and ostructive uropathy", "Congenital abnormalities of kidneys and urinary system"]}, {"unit_no": "Nephrology/Pulmonology - Unit 3", "topics": ["Clinical examination of kidney and genitourinary system- symptoms, signs and investigations.", "Major manifestations - dysuria, pyuria, urethral symptoms", "Disorders of urine volume, haematuria, proteinuria, oedema,", "Obstruction of urinary tract, incontinence, renal involvement in systemic disorders", "Drugs and kidney, renal replacement therapy"]}, {"unit_no": "Nephrology/Pulmonology - Unit 4", "topics": ["Upper airway diseases- basic respiratory mechanics, causes and pathophysiology of hypoxia and hypercapnia.", "R