  ('1742', 'Hospital organization & administration , medical ethics & consumer protection act', 3, $ahs${"academic_year": 3, "subjects": [{"subject_no": "Paper II", "title": "Hospital organization & administration , medical ethics & consumer protection act", "mode": "units", "topics": [], "units": [{"unit_no": "I. HOSPITAL ORGANIZATION AND ADMINISTRATION - 1. Introduction to Hospital Administration", "topics": ["a) Who's Who in hospital - Key administrators and their functions, overview of medical and para-medical specialities, main service departments:", "b) Overview of health services - government services: private & not for profit: primary, secondary & tertiary health care: types of hospital: community, super - speciality etc."]}, {"unit_no": "II. Principles of Organizational Management", "topics": ["a) Culture, Values and Mission", "b) Organizational Structure", "c) Planning and Controlling", "d) Hospital Organizational Structures - Government, Private and Not for Profit."]}, {"unit_no": "III. Managing People ( Human Resources )", "topics": ["a) Overview - scope and functions of HR dept, HR planning", "b) Recruitment and Appointment", "c) Training and Development", "d) Goal setting, rewards systems and motivation", "e) Performance Appraisal", "f) Promotion, internal transfers", "g) Problems and Legal issues", "h) Leadership", "i) Working in teams"]}, {"unit_no": "IV. Clinical Services", "topics": ["a) Overview of clinical departments and services - OPD, In-patients, ICU, Surgical, Emergency, Community/family Health, Paramedical & Rehabilitation", "b) Types of doctors, their training, roles and responsibilities", "c) The role & responsibilities of the HOD", "d) Medical Audit", "e) Medical Negligence & Litigation"]}, {"unit_no": "V. Nursing Services and Wards", "topics": ["a) Objectives of the nursing service", "b) Nursing service organization, types of nurses, their training, qualifications and functions, other ward staff, personnel issues.", "c) Ward management"]}, {"unit_no": "VI. Product-based services", "topics": ["a) Pharmacy purchasing and stores", "b) Pharmacy dispensing", "c) Prosthetics & Orthotics"]}, {"unit_no": "VII. Diagnostic Services (Radiology, Laboratories, Blood Bank etc)", "topics": ["a) Overview - main services and their functions", "b) In-house services"]}, {"unit_no": "VIII. Patient Services ( non medical )", "topics": ["a) Reception, Welcome/Help Desk", "b) Patient facilities, wheelchairs, Ambulances", "c) Public Relations - objectives, functions, policies, different media, methodologies, networking"]}, {"unit_no": "IX. Managing Support Services", "topics": ["a) Overview of functions of all support services including Laundry, Catering, Cleaning, CSSD, Transport, Security, Materials ( Purchase and Stores ) etc", "b) Functions of GS Office"]}, {"unit_no": "X. Hospital Infrastructure ( Buildings and Plant )", "topics": ["a) Civil Engineering - Planning and maintaining buildings, water & sewage", "b) Electrical Engineering", "c) Mechanical Engineering, Equipment Maintenance, Medical Gases, etc", "d) Biomedical Engineering"]}, {"unit_no": "XI. Hospital Information Systems", "topics": ["a) Analysing information requirements", "b) Reporting systems", "c) Early warning systems", "d) Computerized Systems, intranet"]}, {"unit_no": "2. Managing the Organization ( putting it all together )", "topics": ["a) Planning: strategy and corporate planning", "b) Dealing with risk and uncertainty", "c) Organizational Development and Change management", "d) Corporate Governance & legal matters", "e) Relationships with other institutions and organizations"]}, {"unit_no": "MEDICAL ETHICS & CONSUMER PROTECTION ACT - Laws relating to Hospital Administration", "topics": ["1. Structure of Indian Judicial System: Subordinate courts - Various Tribunals - High court and Supreme court - their working relationships and effect of orders.", "2. Medico - legal cases: IPC - Medical Termination of Pregnancy Act 1971, Transplantation of Human Organs Act.", "3. Law of Contract: Patient as a consumer - Law of Tort - Composition of D.C.D.R.F, S.C.D.R.C and N.C.D.R.C - powers, terms and jurisdiction, enforcement of orders.", "4. Medical Negligence: Negligence - Medical Negligence - Contributory Negligence - Gross Negligence - Criminal Negligence - Onus of Proof - Prevention of such Negligence.", "5. Liability and Compensation: Vicarious Liability - Liability of Medical Professionals and Para-medical staff - Quantum of Compensation - Applicability of provisions of Consumer Protection Act for various institutions.", "6. Consumer Protection Act 1986: Various provisions - structure, powers and jurisdiction of various forums constituted in C.P Act - orders - how enforced.", "7. Consent: Consent - Medical Consent - various types of Consent - Consent forms - \"informed Consent\" in clinical trials - Consent as a process - full proof methods for proper Consent - various defects in obtaining Consent.", "8. Important case studies: District Forums, State Consumer Disputes Redressal Commission - National Consumer Disputes Redressal Commission Case study as how cases were decided."]}], "reference_books": [], "lecture_hours": 150, "notes": "Source heading: BMRSc 3-2 HOSPITAL ORGANIZATION AND ADMINISTRATION, MEDICAL ETHICS & CONSUMER PROTECTION ACT."}], "intro": "Source heading: BMRSc 3-2 HOSPITAL ORGANIZATION AND ADMINISTRATION, MEDICAL ETHICS & CONSUMER PROTECTION ACT."}$ahs$::jsonb, $ahs${"components": [{"name": "Internal Assessment", "max": 50, "min": 25}, {"name": "Theory (University)", "max": 100, "min": 50}, {"name": "Practical", "max": 50, "min": null}, {"name": "Viva Voce", "max": 50, "min": 25}], "question_pattern": {"duration_hours": 3, "sections": [{"name": "SECTION A", "items": [{"type": "Essay type questions", "pattern": "(2*15=30)", "marks": 30}, {"type": "Short notes", "pattern": "(10X5 = 50)", "marks": 50}]}, {"name": "SECTION B", "items": [{"type": "Short answer type questions", "pattern": "(10x 2 = 20